  },
  "data_meaning": {
    "inputs": [
      {"text": "Тип рифа: плосковершинный или атолловидный (кольцо) либо асимметричная система (полоса).", "claims": ["c1", "c5"], "hypothesis": false},
      {"text": "Свойства пород по участкам: гребень, верхний склон, центр, лагуна, зарифовые отложения.", "claims": ["c2", "c4", "c7"], "hypothesis": false}
    ],
    "outputs": [
      {"text": "Форма зоны лучших коллекторов в плане: кольцо или линия вдоль простирания рифов.", "claims": ["c1", "c5"], "hypothesis": false},
      {"text": "Оценка, где фильтрация лучше, а где затруднена или невозможна.", "claims": ["c3", "c4"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Центр рифа и лагуна: фильтрация затруднена или невозможна, но степень в тексте не задана числом.", "claims": ["c4"], "hypothesis": false},
      {"text": "Зарифовые отложения: бедные порами или непроницаемые. Граница между этими случаями в тексте не проведена.", "claims": ["c7"], "hypothesis": false}
    ]
  },
